import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate } from '../remotionShim';
{/* Start Google Fonts Loader */ }
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]); // super light + stable

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */ }



export type NewtonsCradleProps = Record<string, any>;

const Sparks: React.FC<{ x: number; y: number; opacity: number; scale: number }> = ({
  x, y, opacity, scale
}) => {
  if (opacity <= 0) return null;
  return (
    <div style={{
      position: 'absolute',
      left: x,
      top: y,
      opacity,
      transform: `scale(${scale})`,
      pointerEvents: 'none',
      transition: 'none',
    }}>
      <div style={{ position: 'absolute', width: 4, height: 24, backgroundColor: 'white', borderRadius: 2, top: -90, left: -30, transform: 'rotate(-30deg)', transition: 'none' }} />
      <div style={{ position: 'absolute', width: 4, height: 30, backgroundColor: 'white', borderRadius: 2, top: -100, left: -2, transform: 'rotate(0deg)', transition: 'none' }} />
      <div style={{ position: 'absolute', width: 4, height: 24, backgroundColor: 'white', borderRadius: 2, top: -90, left: 26, transform: 'rotate(30deg)', transition: 'none' }} />
    </div>
  );
};

const Pendulum: React.FC<{
  index: number;
  word: string;
  isGlowing: boolean;
  angle: number;
  ballSize: number;
  stringLength: number;
  highlightColor: string;
  startX: number;
  textSize: number;
}> = ({ index, word, isGlowing, angle, ballSize, stringLength, highlightColor, startX, textSize }) => {
  // Counter-rotate the text so it stays upright
  const textRotation = -angle;

  return (
    <div
      style={{
        position: 'absolute',
        top: 0,
        left: startX + index * ballSize,
        width: ballSize,
        height: stringLength + ballSize,
        transformOrigin: 'top center',
        transform: `rotate(${angle}deg)`,
        display: 'flex',
        flexDirection: 'column',
        alignItems: 'center',
        transition: 'none',
      }}
    >
      {/* Pendulum String */}
      <div style={{
        width: 3,
        height: stringLength,
        background: 'linear-gradient(to bottom, rgba(255,255,255,0.05) 0%, rgba(255,255,255,0.8) 100%)',
        borderRadius: 2,
        transition: 'none',
      }} />

      {/* Pendulum Bob */}
      <div style={{
        width: ballSize,
        height: ballSize,
        borderRadius: '50%',
        background: isGlowing
          ? `radial-gradient(circle at 35% 35%, #ffffff 0%, ${highlightColor} 30%, #001144 90%)`
          : 'radial-gradient(circle at 35% 35%, #5a5a5a 0%, #1a1a1a 60%, #050505 100%)',
        boxShadow: isGlowing
          ? `0 0 60px 15px ${highlightColor}88, inset -10px -10px 30px rgba(0,0,0,0.4)`
          : 'inset -15px -15px 40px rgba(0,0,0,0.8), 0 10px 20px rgba(0,0,0,0.3)',
        position: 'relative',
        transition: 'none',
      }}>
      </div>

      {/* Linked Word */}
      <div style={{
        position: 'absolute',
        top: stringLength + ballSize + 40,
        left: -ballSize / 2,
        width: ballSize * 2,
        textAlign: 'center',
        color: isGlowing ? highlightColor : 'white',
        textShadow: isGlowing ? `0 0 15px ${highlightColor}` : 'none',
        fontSize: textSize,
        fontWeight: 700,
        letterSpacing: 2,
        opacity: isGlowing ? 1 : 0.8,
        transform: `rotate(${textRotation}deg)`,
        transformOrigin: 'top center',
        transition: 'none',
      }}>
        {word}
      </div>
    </div>
  );
};

const NewtonsCradle: React.FC<NewtonsCradleProps> = ({
  durationInSeconds = 6,
  backgroundColor = "#08080a",
  transparentBackground = false,
  words = ["YOU", "BUILD", "YOUR", "OWN", "MOMENTUM"],
  highlightColor = "#3b82f6",
  highlightIndex = 4,
  swingAngle = 25,
  loopDurationFrames = 90,
  textSize = 45,
}) => {
  useFontLoader(["Inter"]);

  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  const count = words.length;
  if (count <= 1) return null; // A Newton's cradle requires at least 2 bobs

  // Responsive Layout Calculations
  const ballSize = Math.min(180, (width * 0.85) / count);
  const startX = (width - count * ballSize) / 2;
  const pivotY = -height * 0.15; // Off-screen top
  const ballCenterY = height * 0.65; // Position the bobs nicely in the lower third
  const stringLength = ballCenterY - pivotY - ballSize / 2;

  // Animation Physics
  const halfCycle = loopDurationFrames / 2;
  // Offset the frame start so it begins exactly when the rightmost ball is swung out
  const shiftedFrame = frame + halfCycle / 2;
  const cycleFrame = shiftedFrame % loopDurationFrames;

  // Angle Calculator
  const getAngle = (index: number) => {
    if (index === 0) {
      if (cycleFrame >= halfCycle) {
        const progress = (cycleFrame - halfCycle) / halfCycle;
        // Positive angle rotates clockwise, swinging the bottom to the LEFT
        return swingAngle * Math.sin(progress * Math.PI);
      }
      return 0;
    }
    if (index === count - 1) {
      if (cycleFrame < halfCycle) {
        const progress = cycleFrame / halfCycle;
        // Negative angle rotates counter-clockwise, swinging the bottom to the RIGHT
        return -swingAngle * Math.sin(progress * Math.PI);
      }
      return 0;
    }
    return 0;
  };

  // Impact Sparks Logic
  const leftSparkFrame = cycleFrame;
  const leftSparkOpacity = leftSparkFrame < 15
    ? interpolate(leftSparkFrame, [0, 2, 10], [1, 1, 0], { extrapolateRight: 'clamp' })
    : 0;
  const leftSparkScale = leftSparkFrame < 15
    ? interpolate(leftSparkFrame, [0, 10], [0.5, 1.2], { extrapolateRight: 'clamp' })
    : 0;

  const rightSparkFrame = cycleFrame - halfCycle;
  const rightSparkOpacity = (rightSparkFrame >= 0 && rightSparkFrame < 15)
    ? interpolate(rightSparkFrame, [0, 2, 10], [1, 1, 0], { extrapolateRight: 'clamp' })
    : 0;
  const rightSparkScale = (rightSparkFrame >= 0 && rightSparkFrame < 15)
    ? interpolate(rightSparkFrame, [0, 10], [0.5, 1.2], { extrapolateRight: 'clamp' })
    : 0;

  const leftImpactX = startX + ballSize;
  const rightImpactX = startX + (count - 1) * ballSize;

  // Render variables
  const bgStyle = transparentBackground
    ? { backgroundColor: 'transparent' }
    : { backgroundColor };

  return (
    <AbsoluteFill style={{ ...bgStyle, fontFamily: "Inter" }}>
      
      {/* Pendulum System Container */}
      <div style={{
        position: 'absolute',
        top: pivotY,
        left: 0,
        width: '100%',
        height: '100%',
        transition: 'none'
      }}>
        {words.map((word, index) => (
          <Pendulum
            key={index}
            index={index}
            word={word}
            isGlowing={index === highlightIndex}
            angle={getAngle(index)}
            ballSize={ballSize}
            stringLength={stringLength}
            highlightColor={highlightColor}
            startX={startX}
            textSize={textSize}
          />
        ))}

        {/* Impact Sparks */}
        <Sparks
          x={leftImpactX}
          y={stringLength + ballSize / 2}
          opacity={leftSparkOpacity}
          scale={leftSparkScale}
        />
        <Sparks
          x={rightImpactX}
          y={stringLength + ballSize / 2}
          opacity={rightSparkOpacity}
          scale={rightSparkScale}
        />
      </div>

    </AbsoluteFill>
  );
};

export default NewtonsCradle;